  (172, "el", "en", "Πονάει το πόδι μου."),
  (173, "el", "en", "Η αδερφή μου μαγειρεύει πολύ καλά."),
  (174, "el", "en", "Δεν βρίσκω το κινητό μου."),
  (175, "el", "en", "Θέλουμε να νοικιάσουμε ένα σκάφος."),
  (176, "el", "en", "Πόση ώρα κάνει το ταξίδι;"),
  (177, "el", "en", "Το μάθημα αρχίζει στις εννιά."),
  (178, "el", "en", "Δεν μου αρέσει το γάλα."),
  (179, "el", "en", "Είναι κοντά το λιμάνι;"),
  (180, "el", "en", "Ο αδερφός μου μιλάει γαλλικά."),
  (181, "el", "en", "Θα σε περιμένω στο αεροδρόμιο."),
  (182, "el", "en", "Τα παιδιά είναι στην παραλία."),
  (183, "el", "en", "Μπορούμε να καθίσουμε μέσα;"),
  (184, "el", "en", "Θα πάρω τη μουσακά."),
  (185, "el", "en", "Η τράπεζα είναι κλειστή σήμερα."),
  (186, "el", "en", "Η βρύση στάζει."),
  (187, "el", "en", "Αύριο πάμε εκδρομή."),
  (188, "el", "en", "Ξέχασα την τσάντα μου στο εστιατόριο."),
  (189, "el", "en", "Θα βρέξει αύριο;"),
  (190, "el", "en", "Η γιαγιά μου φτιάχνει τέλεια σπανακόπιτα."),
  (191, "el", "en", "Ζω στην Αθήνα δέκα χρόνια."),
  (192, "el", "en", "Το νερό της βρύσης πίνεται."),
  (193, "el", "en", "Σβήσε το φως."),
  (194, "el", "en", "Χάσαμε το τελευταίο λεωφορείο."),
  (195, "el", "en", "Η αδερφή μου σπουδάζει νομική."),
  (196, "el", "en", "Φοβάμαι τα ύψη."),
  (197, "el", "en", "Η θέα είναι υπέροχη."),
  (198, "el", "en", "Μου καλείτε ένα ταξί;"),
  (199, "el", "en", "Ξέχασα τον κωδικό μου."),
  (200, "el", "en", "Η συναυλία αναβλήθηκε λόγω του καιρού."),
];
